/**
 * @summary Create and publish an announcement
 */
export const createAnnouncementBodyTitleMin = 3;
export const createAnnouncementBodyTitleMax = 180;




export const CreateAnnouncementBody = zod.object({
  "title": zod.string().min(createAnnouncementBodyTitleMin).max(createAnnouncementBodyTitleMax),
  "body": zod.string().min(1)
})

export const CreateAnnouncementResponse = zod.object({
  "id": zod.number().int(),
  "title": zod.string(),
  "body": zod.string(),
  "published": zod.boolean(),
  "createdAt": zod.coerce.date(),
  "isRead": zod.boolean()
})


/**
 * @summary Edit an announcement
 */
export const UpdateAnnouncementParams = zod.object({
  "announcementId": zod.coerce.number().int()
})

export const updateAnnouncementBodyTitleMin = 3;
export const updateAnnouncementBodyTitleMax = 180;




export const UpdateAnnouncementBody = zod.object({
  "title": zod.string().min(updateAnnouncementBodyTitleMin).max(updateAnnouncementBodyTitleMax).optional(),
  "body": zod.string().min(1).optional(),
  "published": zod.boolean().optional()
})

export const UpdateAnnouncementResponse = zod.object({
  "id": zod.number().int(),
  "title": zod.string(),
  "body": zod.string(),
  "published": zod.boolean(),
  "createdAt": zod.coerce.date(),
  "isRead": zod.boolean()
})


